        List<Object[]> objs = dbHelper.statisticMoneyByType(this, this.chooseMonthView.getText().toString());
        if (objs == null) {
            showNoResults();
            return;
        }
        int[] colors = getPieColors(objs);
        double[] datas = getPieDatas(objs);
        String[] labels = getPieLabels(objs);
        String title = getString(R.string.title);
        showEachItemMoney(labels, datas);
        makePieChart(datas, colors, labels, title);
    }

    public int[] getPieColors(List<Object[]> objs) {
        int[] colors = {-16776961, -16711936, -65281, -256, -16711681, -65536};
        int[] myColors = new int[objs.size()];
        for (int i = 0; objs != null && i < objs.size(); i++) {
            myColors[i] = colors[i];
        }
        return myColors;
    }

    public void showEachItemMoney(String[] labels, double[] datas) {
        clearItemInfo();
        for (int i = 0; labels != null && i < labels.length; i++) {
            if (BabyConstant.NAIFEN.equals(labels[i])) {
