    public void makePieChart(double[] datas, int[] colors, String[] labels, String title) {
        try {
            DefaultRenderer defaultRenderer = buildCategoryRenderer(colors, title);
            CategorySeries categorySeries = buildCategoryDataset(title, datas, labels);
            View pie = ChartFactory.getPieChartView(this, categorySeries, defaultRenderer);
            LinearLayout layout = (LinearLayout) findViewById(R.id.chart);
            layout.removeAllViewsInLayout();
            layout.addView(pie, new ViewGroup.LayoutParams(-1, -1));
        } catch (Exception e) {
            e.printStackTrace();
            Toast.makeText(getApplicationContext(), getString(R.string.fail_to_statistic), 1).show();
        }
    }

    public DefaultRenderer buildCategoryRenderer(int[] colors, String title) {
        DefaultRenderer renderer = new DefaultRenderer();
        renderer.setLabelsTextSize(15.0f);
        renderer.setLegendTextSize(15.0f);
        renderer.setMargins(new int[]{20, 30, 15, 10});
        for (int color : colors) {
            SimpleSeriesRenderer r = new SimpleSeriesRenderer();
            r.setColor(color);
            renderer.addSeriesRenderer(r);
        }
        renderer.setChartTitle(title);
        renderer.setChartTitleTextSize(25.0f);
        renderer.setLabelsColor(DefaultRenderer.BACKGROUND_COLOR);
        return renderer;
    }

    public CategorySeries buildCategoryDataset(String title, double[] datas, String[] labels) {
        CategorySeries series = new CategorySeries(title);
        String[] percents = calcPercentages(datas);
        for (int i = 0; i < datas.length; i++) {
            String label = String.valueOf(labels[i]) + "," + percents[i];
            series.add(label, datas[i]);
        }
        return series;
    }

    public String[] calcPercentages(double[] datas) {
        double total = calcTotalMoney(datas);
        DecimalFormat df = new DecimalFormat("0.0");
        String[] percents = new String[datas.length];
        for (int i = 0; datas != null && i < datas.length; i++) {
            double tmp = (datas[i] / total) * 100.0d;
            percents[i] = String.valueOf(df.format(tmp)) + "%";
        }
        return percents;
    }

    public double calcTotalMoney(double[] datas) {
        double total = 0.0d;
        for (int i = 0; datas != null && i < datas.length; i++) {
            total += datas[i];
        }
        return total;
    }

