    public static String calcBabyMonths(Date curDate) {
        String str;
        if ("".equals(BABY_BIRTHDAY)) {
            return "";
        }
        try {
            Date birthDate = DateUtil.formatDate(BABY_BIRTHDAY, "yyyy-MM-dd");
            int days = (int) ((curDate.getTime() - birthDate.getTime()) / TimeChart.DAY);
            int months = days / 30;
            int leftDays = days % 30;
            if (months > 12) {
                int years = months / 12;
                int tmpMonths = months % 12;
                str = String.valueOf(years) + "岁" + tmpMonths + "个月" + leftDays + "天";
            } else {
                str = String.valueOf(months) + "个月" + leftDays + "天";
            }
            return str;
        } catch (Exception e) {
            return "";
        }
    }
}

